def get_fold(u, v, nm):
    from scipy.special import erf
    from scipy.optimize import least_squares
    spec = {'erf': (lambda a, q: erf(q[0] * a) + q[1] * a, [1.5, -1.55]), 'exp': (lambda a, q: a * np.exp(-(q[0] * a) ** 2) + q[1] * a, [1, -0.9]), 'sin': (lambda a, q: np.sin(q[0] * a) + q[1] * a, [2.9, -2.52]), 'poly': (lambda a, q: a + q[0] * a ** 3 + q[1] * a ** 5, [-12, 3]), 'tanh': (lambda a, q: np.tanh(q[0] * a) + q[1] * a, [1.5, -1.4]), 'odd7': (lambda a, q: a + q[0] * a ** 3 + q[1] * a ** 5 + q[2] * a ** 7, [-12, 3, 0])}
    (fun, init) = spec[nm]

    def calc(q):
        d = np.c_[np.ones(len(u)), fun(u, q)]
        c = np.linalg.lstsq(d, v, rcond=None)[0]
        return (c, (d @ c - v).ravel())
    q = least_squares(lambda q: calc(q)[1], init, max_nfev=120).x
    c = calc(q)[0]
    return (fun, q, c)

def white(x):
    (_, s, w) = np.linalg.svd(x - x.mean(0), full_matrices=False)
    return (x - x.mean(0)) @ (w.T / s @ w)

def _coordinates(study, x):
    from scipy.special import erf
    from scipy.optimize import least_squares
    a = study['panel_a']
    (A, v) = (_design(a['u']), a['v'])
    keep = np.ones(len(A), dtype=bool)
    for _ in range(6):
        w = _fit(A[keep], v[keep])
        e = np.linalg.norm(A @ w - v, axis=1)
        good = e < max(0.001, 3 * np.median(e))
        if np.array_equal(keep, good) or good.sum() < A.shape[1]:
            break
        keep = good
    z = np.linalg.solve(w[1:].T, (x - w[0]).T).T
    p = study['panel_b']
    (u, v) = (p['u'], p['v'])

    def phi(q, u):
        return _design(erf(q[0] * u) + q[1] * u)

    def residual(q):
        F = phi(q, u)
        return (F @ _fit(F, v) - v).ravel()
    sols = [least_squares(residual, [a, -0.5 * a], bounds=([0.1, -8], [4, 8]), max_nfev=80) for a in [0.4, 0.8, 1.4, 2.2]]
    q = min(sols, key=lambda o: o.cost).x
    b = phi(q, z) @ _fit(phi(q, u), v)
    return (z, b)
